package runs

import (
	"fmt"
	"net/http"

	"github.com/ryuma04/tapu-sena/backend/internal/httpx"
)

// GET /runs/{id}/report?format=md|json|pdf — the Research & Planning report, generated by the agent
// service from persisted data (brief, settings, plan) so an export never reflects stale browser state.
func (s *Service) Report(w http.ResponseWriter, r *http.Request) error {
	run, _, err := s.loadRun(r, "viewer")
	if err != nil {
		return err
	}
	format := r.URL.Query().Get("format")
	if format == "" {
		format = "md"
	}
	if format != "md" && format != "json" && format != "pdf" {
		return httpx.Errorf(http.StatusBadRequest, "format must be md, json or pdf")
	}
	body, ctype, name, err := s.agents.Download(r.Context(), fmt.Sprintf("/runs/%d/report?format=%s", run.ID, format))
	if err != nil {
		return httpx.Errorf(http.StatusBadGateway, "the report could not be generated right now")
	}
	if name == "" {
		name = fmt.Sprintf("research-report-run-%d.%s", run.ID, format)
	}
	w.Header().Set("Content-Type", ctype)
	w.Header().Set("Content-Disposition", fmt.Sprintf("attachment; filename=%q", name))
	w.Header().Set("Content-Length", fmt.Sprint(len(body)))
	_, _ = w.Write(body)
	return nil
}
